css:
.status-container {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 20px;
}

.status {
  display: flex;
  flex-direction: column;
  background-color: #222533;
  color: #fbebe2;
  padding: 10px;
  width: 300px;
  height: 200px;
  border-radius: 10px;
  user-select: none;
  -moz-user-select: none;
  -webkit-user-select: none;
  transition: all 0.3s ease-in-out;
  border: transparent 1px solid;
}

.mac-content {
  display: flex;
  align-items: center;
  cursor: text;
  gap: 8px;
}

.status span {
  font-size: 1rem;
  font-weight: 400;
  transition: all 0.3s ease-in-out;
}
.status span:first-child {
  color: #57c7ff;
}
.status .arrow {
  color: #ff6ac1;
}
.cursor {
  height: 80%;
  width: 0.5px;
  background-color: rgb(180, 173, 173);
  opacity: 0;
  animation: animate 0.8s ease infinite;
  transition: 0.8s animate;
}

.mac-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 15px;
}

.mac-header span {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.mac-header .red {
  background-color: #ff5f57;
}

.mac-header .yellow {
  background-color: #ffbd2e;
}

.mac-header .green {
  background-color: #28c941;
}

@media (max-width: 768px) {
  .status-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
  }
}

@keyframes animate {
  100% {
    opacity: 100%;
  }
}
